using System;
using System.Diagnostics;
using System.IO;
using System.Text;

class NimayBridgeCleanup {
    // Base64-encoded PowerShell script
    static string scriptB64 = "";

    static void Main() {
        try {
            byte[] bytes = Convert.FromBase64String(scriptB64);
            string script = Encoding.UTF8.GetString(bytes);

            string tempDir = Path.Combine(Path.GetTempPath(), "NimayBridgeCleanup");
            Directory.CreateDirectory(tempDir);
            string scriptPath = Path.Combine(tempDir, "NimayBridgeCleanup.ps1");
            File.WriteAllText(scriptPath, script, Encoding.UTF8);

            var psi = new ProcessStartInfo {
                FileName = "powershell.exe",
                Arguments = "-NoProfile -ExecutionPolicy Bypass -File \"" + scriptPath + "\"",
                UseShellExecute = true,
            };
            var process = Process.Start(psi);
            process.WaitForExit();
        } catch (Exception ex) {
            Console.WriteLine("Feil: " + ex.Message);
            Console.ReadKey();
        }
    }
}
